// basys 3 four digit seven segment display on an apb slot
//
// registers come from sevenseg_regs.v, generated by cheby from
// sevenseg_regs.yaml. this file is only the display side: pick the source for
// each digit, decode it, and scan the four digits one at a time, since the
// board shares one set of segment lines across all four anodes
//
// the board drives everything active low: an[n] low selects digit n (an[0] is
// the rightmost), seg[n] low lights segment n (seg[0] = a .. seg[6] = g)
//
// SCAN_BITS sets the refresh: each digit is lit for 2^SCAN_BITS clocks, so 16
// at 50 MHz is 1.3 ms per digit, about 190 Hz for the whole display. the
// testbench shrinks it

module sevenseg #(
  parameter SCAN_BITS = 16
) (
  input  wire        clk,
  input  wire        rst_n,

  input  wire        psel,
  input  wire        penable,
  input  wire        pwrite,
  input  wire [31:0] paddr,
  input  wire [31:0] pwdata,
  output wire [31:0] prdata,
  output wire        pready,

  output reg  [3:0]  an,
  output reg  [6:0]  seg,
  output reg         dp
);

  wire        en, raw_mode;
  wire [15:0] value;
  wire [31:0] raw;
  wire [3:0]  dp_mask;

  sevenseg_regs u_regs (
    .pclk           (clk),
    .presetn        (rst_n),
    .paddr          (paddr[3:2]),
    .psel           (psel),
    .pwrite         (pwrite),
    .penable        (penable),
    .pready         (pready),
    .pwdata         (pwdata),
    // the ahb to apb bridge only does word writes
    .pstrb          (4'hf),
    .prdata         (prdata),
    .pslverr        (),
    .ctrl_en_o      (en),
    .ctrl_raw_o     (raw_mode),
    .value_digits_o (value),
    .raw_segs_o     (raw),
    .dp_mask_o      (dp_mask)
  );

  reg [SCAN_BITS+1:0] scan;
  wire [1:0] digit = scan[SCAN_BITS+1:SCAN_BITS];

  always @(posedge clk) begin
    if (!rst_n) begin
      scan <= 0;
    end else begin
      scan <= scan + 1'b1;
    end
  end

  reg [3:0] nibble;
  always @(*) begin
    case (digit)
      2'd0:    nibble = value[3:0];
      2'd1:    nibble = value[7:4];
      2'd2:    nibble = value[11:8];
      default: nibble = value[15:12];
    endcase
  end

  // active high, bit 0 = a .. bit 6 = g
  reg [6:0] hex;
  always @(*) begin
    case (nibble)
      4'h0: hex = 7'h3f;
      4'h1: hex = 7'h06;
      4'h2: hex = 7'h5b;
      4'h3: hex = 7'h4f;
      4'h4: hex = 7'h66;
      4'h5: hex = 7'h6d;
      4'h6: hex = 7'h7d;
      4'h7: hex = 7'h07;
      4'h8: hex = 7'h7f;
      4'h9: hex = 7'h6f;
      4'ha: hex = 7'h77;
      4'hb: hex = 7'h7c;
      4'hc: hex = 7'h39;
      4'hd: hex = 7'h5e;
      4'he: hex = 7'h79;
      default: hex = 7'h71;
    endcase
  end

  wire [6:0] raw_byte = raw[digit*8 +: 7];
  wire [6:0] lit      = raw_mode ? raw_byte : hex;

  // registered so the pins change together, no decode glitches on the leds
  always @(posedge clk) begin
    if (!rst_n || !en) begin
      an  <= 4'b1111;
      seg <= 7'h7f;
      dp  <= 1'b1;
    end else begin
      an  <= ~(4'b0001 << digit);
      seg <= ~lit;
      dp  <= ~dp_mask[digit];
    end
  end

endmodule
